// FoundryCreateMutation supplies the typed draft adapter for framework integrations. Defaults fill omitted fields before UUID preparation; no mutators or database calls run here.
func (d MetaDraft) FoundryCreateMutation(defaults foundryquery.Mutation[Meta]) (foundryquery.Mutation[Meta], error) {
	values, err := foundryquery.ReadCreateDefaults((Meta{}).FoundryQuery(), defaults)
	if err != nil {
		return foundryquery.Mutation[Meta]{}, err
	}
	if !d.fieldKey.IsSet() {
		v, err := foundryquery.MutationValue[Meta, string](values, "foundry_model_metadata", "key")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldKey = v
	}
	if !d.fieldOwner.IsSet() {
		v, err := foundryquery.MutationValue[Meta, string](values, "foundry_model_metadata", "owner")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldOwner = v
	}
	if !d.fieldScope.IsSet() {
		v, err := foundryquery.MutationValue[Meta, string](values, "foundry_model_metadata", "scope")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldScope = v
	}
	if !d.fieldSubjectKey.IsSet() {
		v, err := foundryquery.MutationValue[Meta, string](values, "foundry_model_metadata", "subject_key")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldSubjectKey = v
	}
	if !d.fieldIdentity.IsSet() {
		v, err := foundryquery.MutationValue[Meta, foundryvalue.JSON[model.Identity]](values, "foundry_model_metadata", "identity")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldIdentity = v
	}
	if !d.fieldName.IsSet() {
		v, err := foundryquery.MutationValue[Meta, string](values, "foundry_model_metadata", "name")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldName = v
	}
	if !d.fieldVersion.IsSet() {
		v, err := foundryquery.MutationValue[Meta, uint32](values, "foundry_model_metadata", "version")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldVersion = v
	}
	if !d.fieldValue.IsSet() {
		v, err := foundryquery.MutationValue[Meta, foundryvalue.JSON[json.RawMessage]](values, "foundry_model_metadata", "value")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldValue = v
	}
	if !d.fieldCreatedAt.IsSet() {
		v, err := foundryquery.MutationValue[Meta, temporal.DateTime](values, "foundry_model_metadata", "created_at")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldCreatedAt = v
	}
	if !d.fieldUpdatedAt.IsSet() {
		v, err := foundryquery.MutationValue[Meta, temporal.DateTime](values, "foundry_model_metadata", "updated_at")
		if err != nil {
			return foundryquery.Mutation[Meta]{}, err
		}
		d.fieldUpdatedAt = v
	}
	return d.foundryMutation(true)
}
func (d MetaDraft) foundryMutation(create bool) (foundryquery.Mutation[Meta], error) {
	var assignments []foundryquery.Assignment[Meta]
	if v, set := d.fieldKey.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "key", codec.String[string](), v))
	}
	if v, set := d.fieldOwner.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "owner", codec.String[string](), v))
	}
	if v, set := d.fieldScope.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "scope", codec.String[string](), v))
	}
	if v, set := d.fieldSubjectKey.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "subject_key", codec.String[string](), v))
	}
	if v, set := d.fieldIdentity.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "identity", codec.JSON[model.Identity](), v))
	}
	if v, set := d.fieldName.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "name", codec.String[string](), v))
	}
	if v, set := d.fieldVersion.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "version", codec.Unsigned[uint32](), v))
	}
	if v, set := d.fieldValue.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "value", codec.JSON[json.RawMessage](), v))
	}
	if v, set := d.fieldCreatedAt.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "created_at", codec.DateTime(), v))
	}
	if v, set := d.fieldUpdatedAt.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Meta]("foundry_model_metadata", "updated_at", codec.DateTime(), v))
	}
	return foundryquery.Change(assignments...), nil
}

