// IsEmpty reports whether no fields have been selected for mutation.
func (d MetaDraft) IsEmpty() bool {
	return !d.fieldKey.IsSet() && !d.fieldOwner.IsSet() && !d.fieldScope.IsSet() && !d.fieldSubjectKey.IsSet() && !d.fieldIdentity.IsSet() && !d.fieldName.IsSet() && !d.fieldVersion.IsSet() && !d.fieldValue.IsSet() && !d.fieldCreatedAt.IsSet() && !d.fieldUpdatedAt.IsSet()
}

