// MetaAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func MetaAuditFields(history record.Model[Meta, string]) (MetaAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	var fields MetaAuditFieldSet
	fields.Key, err = record.ReadField(view, "key", codec.String[string]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Owner, err = record.ReadField(view, "owner", codec.String[string]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Scope, err = record.ReadField(view, "scope", codec.String[string]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.SubjectKey, err = record.ReadField(view, "subject_key", codec.String[string]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Identity, err = record.ReadField(view, "identity", codec.JSON[model.Identity]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Name, err = record.ReadField(view, "name", codec.String[string]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Version, err = record.ReadField(view, "version", codec.Unsigned[uint32]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.Value, err = record.ReadField(view, "value", codec.JSON[json.RawMessage]())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.CreatedAt, err = record.ReadField(view, "created_at", codec.DateTime())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	fields.UpdatedAt, err = record.ReadField(view, "updated_at", codec.DateTime())
	if err != nil {
		return MetaAuditFieldSet{}, err
	}
	return fields, nil
}

// MetaAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func MetaAuditing(policy MetaAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Meta]()
		if err != nil {
			return err
		}
		return RegisterMetaObserver(registrar, pool, NewMetaObserver(name), func(resolver foundation.Resolver) (func() MetaHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() MetaHooks {
				write := func(ctx context.Context, tx *database.Tx, changes MetaChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return MetaHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
